using SpheroidalWaves, Test

@testset "Quad angular origin and endpoint precision" begin
    lib = SpheroidalWaves.backend_library(;precision=:quad)
    if lib === nothing || !isfile(lib)
        @info "Skipping quad angular precision references: backend unavailable"
    else
    setprecision(BigFloat,256) do
        # Direct user-supplied Wolfram values, embedded in this test.
        cases = (
            (1,1,big"0.99999999999999999999",big"-2.301112706215036020011242122509447123295245283917268939039451127926383217315674733290126393090031802081648396300088965e-11"),
            (0,2,big"0",big"-0.427292880720811382968058194313112037521173128267084567891239976"),
        )
        for (m,n,x,expected) in cases
            @test only(smn(m,n,big"5",[x];precision=:quad).value) ≈ expected rtol=big"1e-30" atol=0
        end
    end

    # Inline 384-bit independent Legendre-expansion references.
    for (spheroid,m,n,expected) in (
        (:prolate,0,2,complex(parse(BigFloat,"-0.427292880720811382968058194313112037521173128267084567891239976643318637773914509338865193295715914126917231188560358"),parse(BigFloat,"0.0"))),
        (:prolate,0,4,complex(parse(BigFloat,"0.315544761147927311886825514518306719826998866267092012390908562046445358609306930164248836084167818324568640478433955"),parse(BigFloat,"0.0"))),
        (:prolate,1,3,complex(parse(BigFloat,"1.40236054046492242645410416904809208855343776254171498409303287728113430870431950402974382681596395448500148682447835"),parse(BigFloat,"0.0"))),
        (:prolate,2,4,complex(parse(BigFloat,"-7.28732681185378541543842485425923947278114491809990082346812845086960750207761877740403778336454206919551056914348629"),parse(BigFloat,"0.0"))),
        (:oblate,0,2,complex(parse(BigFloat,"-0.424308980981379499521272905416777675613208304102320078949884513869074667575239539339796146340272795348901172094111759"),parse(BigFloat,"0.0"))),
        (:oblate,0,4,complex(parse(BigFloat,"0.451312799424476653401777988212800577593280059631512839182423376165030946753870526217908944653909307222118440520745537"),parse(BigFloat,"0.0"))),
        (:oblate,1,3,complex(parse(BigFloat,"1.70972077212874486887926325850222022754473687950655157430805594313602808378250665672227151672968486777604193876226674"),parse(BigFloat,"0.0"))),
        (:oblate,2,4,complex(parse(BigFloat,"-8.72164032460330237681732756178356975409801315294916903335303557746213008846474533905317107691355407926161094032898508"),parse(BigFloat,"0.0"))),
    )
        for precision in (:double,:quad)
            lib = SpheroidalWaves.backend_library(;precision)
            if lib === nothing || !isfile(lib)
                @info "Skipping angular origin comparisons: backend unavailable" precision
                continue
            end
            c=precision === :quad ? big"5" : 5.0
            scalar=smn(m,n,c,[0];spheroid,precision)
            batch=smn(m,n,c,[0,1//1000];spheroid,precision)
            tolerance=precision === :quad ? big"1e-28" : big"1e-12"
            @test only(scalar.value) ≈ expected rtol=tolerance atol=0
            @test only(scalar.value) ≈ batch.value[1] rtol=tolerance atol=0
            @test only(scalar.derivative) == 0
        end
    end

