        xs = setprecision(BigFloat,384) do
            [sign*(1-d) for d in (big"1e-6",big"1e-12",big"1e-20",big"1e-40") for sign in (1,-1)]
        end
        reference = (;xs,values,norm)
        setprecision(BigFloat,256) do
            c=ci == "0" ? parse(BigFloat,cr) : complex(parse(BigFloat,cr),parse(BigFloat,ci))
            xs=BigFloat.(reference.xs)
            result=smn(m,n,c,xs;spheroid,precision=:quad)
            for (i,expected) in enumerate(reference.values)
                @test result.value[i] ≈ expected.value rtol=big"1e-28" atol=0
                @test result.derivative[i] ≈ expected.derivative rtol=big"1e-28" atol=0
            end
            normalized=smn(m,n,c,xs[1:2];spheroid,precision=:quad,normalize=true)
            @test normalized.value ≈ result.value[1:2]/reference.norm rtol=big"1e-28"
            @test normalized.derivative ≈ result.derivative[1:2]/reference.norm rtol=big"1e-28"
            @test all(==(-1),accuracy(m,n,c,xs[1:2];spheroid,precision=:quad,target=:angular))
        end
    end

    xs=[big"0",1-big"1e-20",-1+big"1e-40"]
    degrees=smn(1,1:4,big"5",xs;precision=:quad)
    for n in 1:4
        scalar=smn(1,n,big"5",xs;precision=:quad)
        @test degrees.value[:,n] == scalar.value
        @test degrees.derivative[:,n] == scalar.derivative
    end
    end
